INSERT INTO edu_cards (id, title, body, emoji, bands, status, sort_order) VALUES
(1, 'Água, a amiga de todo dia', 'Quando dá sede, a gente bebe água. Água fresquinha, no copo ou na garrafinha. Que tal escolher um copo especial só seu? Depois de brincar, vamos beber água juntos!', '💧', '3-6', 'rascunho', 10),
(2, 'Um prato colorido', 'Vamos contar as cores do prato? Tem o verde da couve. O laranja da cenoura. O vermelho do tomate. Quanto mais cores, mais divertido fica. Hoje, qual cor você quer provar?', '🌈', '3-6', 'rascunho', 20),
(3, 'Lanche de verdade', 'Hora do lanche! Pode ser uma fruta. Um pedaço de pão. Um iogurte natural. Comida simples, feita de coisas de verdade. Na feira, você pode me ajudar a escolher a fruta.', '🍌', '3-6', 'rascunho', 30),
(4, 'Hora de dormir', 'A noite chegou. É hora de o dia descansar. Banho, dentes escovados e uma história. Luz baixinha. Um abraço. Boa noite! Quem dorme bem acorda com vontade de brincar.', '😴', '3-6', 'rascunho', 40),
(5, 'Tela desligada, brincadeira ligada', 'A tela também precisa descansar. Vamos brincar de esconde-esconde? Montar uma torre de blocos? Desenhar seu bicho preferido? Brincar junto é muito mais gostoso.', '🧸', '3-6', 'rascunho', 50),
(6, 'Pula, corre, dança!', 'Você sabe pular como um sapo? Correr como um cachorrinho? Dançar como uma borboleta? Brincar e se mexer deixa o dia mais alegre. Vamos brincar lá fora?', '🤸', '3-6', 'rascunho', 60),
(7, 'Todo mundo à mesa', 'Na hora de comer, a família senta junto. A gente conversa. Conta como foi o dia. Sem pressa. Sem tela. Comer junto é um momento de carinho.', '🍽️', '3-6', 'rascunho', 70),
(8, 'Fome de verdade', 'Às vezes a gente sente fome. Às vezes é cansaço, tédio ou tristeza. Para a fome, comida gostosa na hora certa. Para a tristeza, um abraço e uma conversa. Como você está se sentindo agora?', '🤗', '3-6', 'rascunho', 80),
(9, 'Provar coisas novas', 'Um alimento novo é uma aventura! Pode cheirar. Pode tocar. Pode dar uma mordidinha. Se não gostar hoje, tudo bem. Outro dia a gente tenta de novo, de outro jeito.', '🥕', '3-6', 'rascunho', 90),
(10, 'Pequeno ajudante na cozinha', 'Lavar as frutas. Mexer a massa. Arrumar os guardanapos. Na cozinha, toda ajuda conta! E quem ajuda a preparar fica com mais vontade de provar.', '👩‍🍳', '3-6', 'rascunho', 100),
(11, 'Missão garrafinha', 'Desafio do dia: levar sua garrafinha de água para a escola e trazer de volta vazia! Água é a melhor bebida para matar a sede depois do recreio, do futebol ou da aula de educação física. Dica de mestre: deixe a garrafinha sempre à vista. Quem vê, lembra!', '💧', '7-10', 'rascunho', 110),
(12, 'Detetive das cores', 'Vire detetive na hora do almoço: quantas cores tem no seu prato? Verde, laranja, roxo, vermelho... Cada cor de fruta, legume e verdura traz coisas boas diferentes. Seu desafio da semana: provar uma cor nova e contar para alguém o que achou.', '🥦', '7-10', 'rascunho', 120),
(13, 'Lanche campeão', 'Lanche bom é feito de comida de verdade: fruta, pão, ovo cozido, castanhas, iogurte natural. Biscoito recheado, salgadinho de pacote e bebida adoçada ficam para de vez em quando, porque vêm cheios de ingredientes com nomes que nem dá para pronunciar. Que tal montar seu lanche com a família na noite anterior?', '🍎', '7-10', 'rascunho', 130),
(14, 'Recarregar as baterias', 'Sabia que dormir é como recarregar uma bateria? Enquanto você dorme, sua mente guarda tudo o que aprendeu no dia. Para dormir melhor: horário certinho, quarto escurinho e celular ou tablet bem longe da cama. Amanhã você acorda pronto para mais aventuras!', '🔋', '7-10', 'rascunho', 140),
(15, 'Pausa no jogo', 'Jogos e vídeos são legais, mas o mundo lá fora também é! Combine com sua família os horários de tela e use um alarme para lembrar de parar. Na pausa, que tal pega-pega, pular corda, bola ou bicicleta? Desafio: inventar uma brincadeira nova sem nenhuma tela.', '🎮', '7-10', 'rascunho', 150),
(16, 'Bora brincar!', 'Correr, pular, dançar, nadar, andar de bicicleta, jogar bola, brincar de amarelinha... Tudo isso vale! O importante é se mexer e se divertir todos os dias, do seu jeito. Chame um amigo, um irmão ou alguém da família e escolham juntos a brincadeira de hoje.', '⚽', '7-10', 'rascunho', 160),
(17, 'Crítico de comida', 'Comer à mesa, com a família, é bem melhor do que comer correndo ou na frente da TV. Dá para sentir o gosto, conversar e rir junto. Experimente comer devagar e descobrir os sabores: é salgado? Azedinho? Crocante? Macio? Vire um crítico de comida!', '🍽️', '7-10', 'rascunho', 170),
(18, 'Fome ou outra coisa?', 'Às vezes dá vontade de comer quando, na verdade, a gente está entediado, chateado ou cansado. Antes de abrir o armário, pergunte: estou com fome de verdade? Se for tédio, uma brincadeira resolve. Se for tristeza, conversar com alguém de confiança ajuda muito. Se for fome, é hora de uma refeição gostosa!', '🤔', '7-10', 'rascunho', 180),
(19, 'Café da manhã de campeão', 'Começar o dia com café da manhã dá energia para aprender, brincar e prestar atenção na aula. Pode ser fruta, pão, ovo, leite, cuscuz, tapioca... Comida simples e de verdade. Dica: acordar um pouquinho mais cedo dá tempo de comer com calma.', '🥣', '7-10', 'rascunho', 190),
(20, 'Aventura ao ar livre', 'Praça, parque, quintal, praia ou rua tranquila: brincar ao ar livre é uma aventura! Dá para observar passarinhos, catar folhas, correr e inventar jogos. Peça para alguém da família levar você a um lugar novo nesta semana.', '🌳', '7-10', 'rascunho', 200),
(21, 'Por que água?', 'Sabia que até a concentração na hora de estudar pode cair quando a gente esquece de beber água? Ter uma garrafa por perto facilita. Refrigerantes e sucos de caixinha costumam ter muito açúcar e não matam a sede como a água. Se achar água sem graça, experimente rodelas de limão, folhas de hortelã ou pedaços de fruta.', '💧', '11-14', 'rascunho', 210),
(22, 'Comida de verdade ou produto de fábrica?', 'Já leu a lista de ingredientes de um salgadinho? Ultraprocessados são produtos de fábrica com ingredientes que a gente não usa em casa: corantes, aromatizantes, realçadores de sabor. O Guia Alimentar para a População Brasileira recomenda basear as refeições em comida de verdade, como arroz, feijão, legumes, frutas, ovos e carnes. Desafio: compare dois rótulos e veja qual tem a lista mais curta.', '🔍', '11-14', 'rascunho', 220),
(23, 'Lanches que dão energia', 'Entre uma aula e outra, um lanche ajuda a manter a energia. Boas opções: frutas, sanduíche de pão com queijo, pipoca feita em casa, castanhas, iogurte natural. Planejar o lanche com a família evita a compra por impulso na cantina. Você pode até inventar suas próprias combinações.', '🥪', '11-14', 'rascunho', 230),
(24, 'Sono, o superpoder esquecido', 'Nessa fase, é comum o sono querer chegar mais tarde. Mas dormir bem melhora a memória, o humor e a disposição para o que você gosta de fazer. Algumas ideias: manter horários parecidos todos os dias, deixar o celular fora do quarto à noite e trocar a tela por um livro ou uma música calma antes de deitar.', '🌙', '11-14', 'rascunho', 240),
(25, 'Você no controle das telas', 'Apps e jogos são feitos para prender a atenção, por isso é tão difícil parar. Uma estratégia é decidir antes: quanto tempo vou usar e para quê? Desativar notificações e deixar o celular longe nas refeições e na hora de dormir ajudam você a ficar no comando. Repare em como se sente depois de uma pausa.', '📱', '11-14', 'rascunho', 250),
(26, 'Movimento do seu jeito', 'Não precisa ser atleta para se movimentar. Skate, dança, vôlei, caminhada com amigos, bicicleta, artes marciais, brincar com o cachorro: vale tudo o que você curte. Experimentar atividades diferentes ajuda a descobrir do que gosta. Que tal chamar alguém para ir junto?', '🛹', '11-14', 'rascunho', 260),
(27, 'Refeições com hora marcada', 'Ter horários mais ou menos fixos para café da manhã, almoço, lanche e jantar ajuda a chegar à mesa com fome, sem ficar beliscando o dia todo. Comer com calma, sentado e sem tela também deixa a refeição mais gostosa. Que tal propor em casa um jantar sem celulares, com todo mundo junto?', '🍲', '11-14', 'rascunho', 270),
(28, 'Emoções e comida', 'Ansiedade, tédio, tristeza ou estresse podem dar vontade de comer mesmo sem fome. Isso acontece com todo mundo. O primeiro passo é perceber: o que estou sentindo agora? Às vezes ajuda mais ouvir música, sair para caminhar, escrever ou conversar com alguém. Se as emoções estiverem difíceis demais, conte para um adulto de confiança.', '💭', '11-14', 'rascunho', 280),
(29, 'Cozinhar é uma aventura', 'Aprender a cozinhar dá autonomia e é divertido. Comece com algo simples: uma omelete, uma salada colorida, uma vitamina de frutas. Peça para alguém da família ensinar uma receita da casa e anote do seu jeito. Cozinhar também é um ótimo jeito de passar tempo com quem você gosta.', '🍳', '11-14', 'rascunho', 290),
(30, 'Explorando a feira', 'Feiras e mercados são cheios de descobertas: frutas da estação, legumes que você nunca provou, temperos com cheiros diferentes. Na próxima ida, escolha um alimento novo para experimentar e procure uma receita com ele. Alimentos da estação costumam ser mais saborosos e mais baratos.', '🧺', '11-14', 'rascunho', 300),
(31, 'Água sempre por perto', 'Escola, trabalho, cursinho, treino: a rotina corre e a água fica para depois. Deixar uma garrafa reutilizável na mochila resolve boa parte disso. Energéticos, refrigerantes e sucos industrializados costumam ter muito açúcar ou cafeína e não substituem a água. Você escolhe o que funciona na sua rotina.', '💧', '15-19', 'rascunho', 310),
(32, 'Lendo rótulos', 'Lista de ingredientes longa, cheia de nomes que você não reconhece, costuma indicar um ultraprocessado. O Guia Alimentar para a População Brasileira propõe uma regra simples: prefira alimentos in natura ou minimamente processados e prepare suas refeições com eles. Ler rótulos é uma forma de decidir por conta própria, sem depender da propaganda.', '🧾', '15-19', 'rascunho', 320),
(33, 'Comer bem fora de casa', 'Na rua, no trabalho ou na faculdade dá para fazer boas escolhas: um prato feito com arroz, feijão, salada e uma proteína costuma ser uma ótima opção. Levar marmita e um lanche de casa, como fruta, sanduíche ou castanhas, também ajuda a economizar. Planejar um pouco a semana evita depender de fast-food.', '🍱', '15-19', 'rascunho', 330),
(34, 'Sono e desempenho', 'Dormir bem faz diferença na memória, no humor, na concentração e até na vontade de fazer as coisas. Na adolescência o relógio interno tende a atrasar, e as telas à noite atrasam ainda mais. Experimente horários regulares, inclusive no fim de semana, celular no silencioso longe da cama e um ritual curto para desacelerar. Teste por duas semanas e veja o que muda.', '🌙', '15-19', 'rascunho', 340),
(35, 'Seu tempo, suas regras', 'Redes sociais são desenhadas para você continuar rolando a tela. Retomar o controle pode ser simples: desativar notificações que não importam, definir horários sem celular, tirar o aparelho da mesa nas refeições. Vale também observar como você se sente depois de usar cada app e ajustar a partir disso.', '📵', '15-19', 'rascunho', 350),
(36, 'Movimento que cabe na rotina', 'Não precisa de academia nem de equipamento caro. Caminhar ou pedalar até a escola, subir escadas, dançar, jogar com os amigos, treinar em casa com vídeos gratuitos: tudo conta. A melhor atividade é a que você curte e consegue manter. Se movimentar também ajuda a lidar com o estresse e a dormir melhor.', '🚴', '15-19', 'rascunho', 360),
(37, 'Não pule refeições', 'Na correria, é comum pular o café da manhã ou o almoço e chegar com muita fome no fim do dia. Manter horários mais regulares ajuda a ter energia o dia todo e a comer com mais tranquilidade. Se a rotina é apertada, deixar algo prático pronto, como fruta, pão ou ovos cozidos, faz diferença.', '⏰', '15-19', 'rascunho', 370),
(38, 'Fome física ou emocional?', 'A fome física vem aos poucos e passa depois de comer. A vontade que vem das emoções costuma ser repentina, pedir algo específico e aparecer em momentos de estresse, tédio ou ansiedade. Perceber a diferença não é se cobrar: é se conhecer. Se a relação com a comida estiver difícil, conversar com a equipe que cuida de você pode ajudar muito.', '🧠', '15-19', 'rascunho', 380),
(39, 'Cozinhar é autonomia', 'Saber preparar algumas refeições básicas é uma habilidade para a vida toda: arroz, feijão, um refogado de legumes, ovos mexidos, um macarrão com molho caseiro. Comece com receitas simples, peça dicas em casa e vá ajustando ao seu gosto. Cozinhar com os amigos também é um ótimo programa.', '🍝', '15-19', 'rascunho', 390),
(40, 'Comer junto', 'Mesmo com horários diferentes, fazer algumas refeições com a família ou com os amigos vale a pena: é tempo de conversa, de trocar ideias e de desacelerar. Que tal propor um almoço de fim de semana em que cada pessoa prepara um prato?', '🤝', '15-19', 'rascunho', 400)
