-- Cartoes educativos "Para voce ler" (ids fixos 1..40; cadastros proprios comecam em 1000).
-- Entram como RASCUNHO: so aparecem no portal depois da revisao e publicacao pela medica.
-- Recarregar e no-op: nunca sobrescreve edicoes nem a publicacao.
-- Faixas: 3-6 (frases curtas para os pais lerem junto), 7-10 (ludico, direto a crianca),
-- 11-14 (respeitoso, curioso), 15-19 (tom de adolescente, autonomia).
ON DUPLICATE KEY UPDATE id = id;
